<?php require_once __DIR__.'/app/core/bootstrap.php'; $title='Accommodation in Arusha'; $rows=query("SELECT * FROM accommodations WHERE status IN ('active','pending') ORDER BY status='active' DESC,id DESC")->fetch_all(MYSQLI_ASSOC); require __DIR__.'/app/views/header.php'; ?>
<section class="section"><div class="section-head"><div><div class="eyebrow" style="color:var(--green)">Stay</div><h2>Accommodation in Arusha</h2><p class="muted">Compare options and select a stay while building your trip.</p></div></div><div class="grid"><?php foreach($rows as $r): ?><article class="card"><div class="card-img"><img src="<?=e(media_url($r['image']))?>" alt=""></div><div class="card-body"><div class="row-between"><span class="tag <?=($r['status']!=='active'?'pending':'')?>"><?=ucfirst($r['status'])?></span><span class="muted"><?=e($r['type'])?></span></div><h3><?=e($r['name'])?></h3><p class="muted"><?=e($r['location'])?> · Up to <?=$r['max_guests']?> guests</p><p><?=e($r['description'])?></p><div class="row-between"><span class="price"><?=money((float)$r['price_per_night'])?> <small>/ night</small></span><?php if($r['status']==='active'): ?><span class="muted">Selectable at booking</span><?php else: ?><span class="muted">Not bookable yet</span><?php endif; ?></div></div></article><?php endforeach; ?></div></section>
